////////////////////////////////////////////////////////////////////////////////
// The arena
//
//   [0, IMAGE_BASE)          never mapped
//   [IMAGE_BASE, image_end)  the program: variables, type descriptors, constants
//   [stack_lo, stack_hi)     the stack
//   [stack_hi, ARENA_SIZE)   the heap
////////////////////////////////////////////////////////////////////////////////
#define ARENA_SIZE 0x7C000000u
#define STACK_SIZE 0x01000000u

static uint8_t* arena     = NULL;
static uint32_t stack_hi  = 0;
static uint32_t heap_next = 0; // The first byte of the heap that was never given out.
static uint32_t committed = 0; // Windows commits memory as the heap grows.

#define P32(off) ((uint32_t*)(arena + (off)))
#define I32(off) ((int32_t*)(arena + (off)))

static void commit(uint32_t upto)
{
#if defined(_WIN32)
	if (upto > committed) {
		uint32_t to = (upto + 0x3FFFFFu) & ~0x3FFFFFu;
		if (to > ARENA_SIZE) {
			to = ARENA_SIZE;
		}
		if (!VirtualAlloc(arena + committed, to - committed, 0x1000 /* MEM_COMMIT */, 0x04 /* PAGE_READWRITE */)) {
			bb_runtime_error("Out of memory");
		}
		committed = to;
	}
#else
	(void)upto;
#endif
}

uint8_t* bb32_arena(uint32_t image_size)
{
	if (arena) {
		return arena;
	}
	uint32_t image_end = (BB32_IMAGE_BASE + image_size + 0xFFFFu) & ~0xFFFFu;
#if defined(_WIN32)
	arena = (uint8_t*)VirtualAlloc(NULL, ARENA_SIZE, 0x2000 /* MEM_RESERVE */, 0x04);
	committed = BB32_IMAGE_BASE;
	if (arena) {
		// The page of null stays reserved, the rest up to the end of the stack is committed.
	}
#else
	arena = (uint8_t*)mmap(NULL, ARENA_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
	if (arena == (uint8_t*)MAP_FAILED) {
		arena = NULL;
	}
#endif
	if (!arena) {
		fputs("Out of memory.\n", stderr);
		exit(1);
	}
#if !defined(_WIN32)
	mprotect(arena, BB32_IMAGE_BASE, PROT_NONE);
#endif
	stack_hi  = image_end + STACK_SIZE;
	heap_next = stack_hi;
	commit(stack_hi + 0x100000u);
	return arena;
}

void bb32_segment(uint32_t offset, const void* data, uint32_t size)
{
	memcpy(arena + offset, data, size);
}

uint32_t bb32_stack_top(void)
{
	return stack_hi - 16;
}

////////////////////////////////////////////////////////////////////////////////
// Heap: blocks of the size classes in free lists, behind a header of 8 bytes that holds the class.
////////////////////////////////////////////////////////////////////////////////
static uint32_t free_lists[64];

static uint32_t size_class(uint32_t size, uint32_t* capacity)
{
	if (size <= 256) {
		uint32_t c = (size + 7) / 8;
		if (c == 0) {
			c = 1;
		}
		*capacity = c * 8;
		return c;
	}
	uint32_t c = 33, cap = 512;
	while (cap < size) {
		cap <<= 1;
		c++;
	}
	*capacity = cap;
	return c;
}

uint32_t bb32_malloc(uint32_t size)
{
	uint32_t capacity;
	uint32_t c = size_class(size, &capacity);
	if (free_lists[c]) {
		uint32_t block = free_lists[c];
		free_lists[c]  = *P32(block);
		return block;
	}
	uint64_t at = (uint64_t)heap_next + 8;
	if (at + capacity > ARENA_SIZE) {
		bb_runtime_error("Out of memory");
		return 0;
	}
	commit((uint32_t)(at + capacity));
	*P32(heap_next)     = c;
	*P32(heap_next + 4) = capacity;
	heap_next           = (uint32_t)(at + capacity);
	return (uint32_t)at;
}

void bb32_free(uint32_t block)
{
	if (!block) {
		return;
	}
	uint32_t c = *P32(block - 8);
	*P32(block)  = free_lists[c];
	free_lists[c] = block;
}

static uint32_t bb32_zalloc(uint32_t size)
{
	uint32_t block = bb32_malloc(size);
	memset(arena + block, 0, size);
	return block;
}

////////////////////////////////////////////////////////////////////////////////
// Strings
////////////////////////////////////////////////////////////////////////////////
typedef struct {
	char*    text;
	size_t   length;
	uint32_t cstr; // Copy in the arena for bb32_str_to_cstr, 0 if there is none.
} bb32_string;

static bb32_string* strings      = NULL;
static uint32_t     string_count = 1; // Handle 0 is no string.
static uint32_t     string_cap   = 0;
static uint32_t*    string_free  = NULL;
static uint32_t     string_free_count = 0;
static uint32_t     string_free_cap   = 0;

static uint32_t string_alloc(char* text, size_t length)
{
	uint32_t handle;
	if (string_free_count) {
		handle = string_free[--string_free_count];
	} else {
		if (string_count >= string_cap) {
			string_cap = string_cap ? string_cap * 2 : 1024;
			strings    = (bb32_string*)realloc(strings, string_cap * sizeof(bb32_string));
			if (!strings) {
				fputs("Out of memory.\n", stderr);
				exit(1);
			}
		}
		handle = string_count++;
	}
	strings[handle].text   = text;
	strings[handle].length = length;
	strings[handle].cstr   = 0;
	return handle;
}

static char* text_copy(const char* s, size_t n)
{
	char* t = (char*)malloc(n + 1);
	if (!t) {
		fputs("Out of memory.\n", stderr);
		exit(1);
	}
	memcpy(t, s, n);
	t[n] = 0;
	return t;
}

uint32_t bb32_str_from_text(const char* text)
{
	text = text ? text : "";
	size_t n = strlen(text);
	return string_alloc(text_copy(text, n), n);
}

uint32_t bb32_str_take_text(char* text)
{
	if (!text) {
		return string_alloc(text_copy("", 0), 0);
	}
	size_t n = strlen(text);
	return string_alloc(text, n); // Already allocated by the runtime with malloc.
}

const char* bb32_str_text(uint32_t str)
{
	return str ? strings[str].text : "";
}

void bb32_str_release(uint32_t str)
{
	if (!str) {
		return;
	}
	if (strings[str].cstr) {
		bb32_free(strings[str].cstr);
	}
	free(strings[str].text);
	strings[str].text = NULL;
	if (string_free_count == string_free_cap) {
		string_free_cap = string_free_cap ? string_free_cap * 2 : 1024;
		string_free     = (uint32_t*)realloc(string_free, string_free_cap * sizeof(uint32_t));
	}
	string_free[string_free_count++] = str;
}

uint32_t bb32_str_load(uint32_t var)
{
	uint32_t s = *P32(var);
	return s ? bb32_str_from_text(strings[s].text) : bb32_str_from_text("");
}

void bb32_str_store(uint32_t var, uint32_t str)
{
	bb32_str_release(*P32(var));
	*P32(var) = str;
}

int32_t bb32_str_compare(uint32_t lhs, uint32_t rhs)
{
	int n = strcmp(strings[lhs].text, strings[rhs].text);
	bb32_str_release(lhs);
	bb32_str_release(rhs);
	return n < 0 ? -1 : (n > 0 ? 1 : 0);
}

uint32_t bb32_str_concat(uint32_t s1, uint32_t s2)
{
	bb32_string* a = &strings[s1];
	bb32_string* b = &strings[s2];
	a->text = (char*)realloc(a->text, a->length + b->length + 1);
	if (!a->text) {
		fputs("Out of memory.\n", stderr);
		exit(1);
	}
	memcpy(a->text + a->length, b->text, b->length + 1);
	a->length += b->length;
	if (a->cstr) {
		bb32_free(a->cstr);
		a->cstr = 0;
	}
	bb32_str_release(s2);
	return s1;
}

int32_t bb32_str_to_int(uint32_t str)
{
	int32_t n = bb_str_to_i32(strings[str].text);
	bb32_str_release(str);
	return n;
}

uint32_t bb32_str_from_int(int32_t n)
{
	return bb32_str_take_text((char*)bb_str_from_i64(n));
}

float bb32_str_to_float(uint32_t str)
{
	float n = (float)bb_str_to_f64(strings[str].text);
	bb32_str_release(str);
	return n;
}

uint32_t bb32_str_from_float(float n)
{
	return bb32_str_take_text((char*)bb_str_from_f64((double)n));
}

uint32_t bb32_str_const(uint32_t cstr)
{
	return bb32_str_from_text((const char*)(arena + cstr));
}

uint32_t bb32_cstr_to_str(uint32_t cstr)
{
	return cstr ? bb32_str_from_text((const char*)(arena + cstr)) : bb32_str_from_text("");
}

uint32_t bb32_str_to_cstr(uint32_t str)
{
	bb32_string* s = &strings[str];
	if (!s->cstr) {
		s->cstr = bb32_malloc((uint32_t)s->length + 1);
		memcpy(arena + s->cstr, s->text, s->length + 1);
	}
	return s->cstr;
}

////////////////////////////////////////////////////////////////////////////////
// Types and objects
//
// BBObj      { fields, next, prev, type, ref_cnt }                       20 bytes
// BBObjType  { tag, used (BBObj), free (BBObj), fieldCnt, fieldTypes[] } fields at 48
// A handle number follows the fields of every object (the original keeps it in a map).
////////////////////////////////////////////////////////////////////////////////
#define OBJ_FIELDS(o) (*P32((o) + 0))
#define OBJ_NEXT(o)   (*P32((o) + 4))
#define OBJ_PREV(o)   (*P32((o) + 8))
#define OBJ_TYPE(o)   (*P32((o) + 12))
#define OBJ_REFS(o)   (*I32((o) + 16))
#define OBJ_SIZE      20u
#define TYPE_TAG(t)   (*I32((t) + 0))
#define TYPE_USED(t)  ((t) + 4)
#define TYPE_FREE(t)  ((t) + 24)
#define TYPE_COUNT(t) (*I32((t) + 44))
#define TYPE_FIELD(t, k) (*P32((t) + 48 + 4 * (uint32_t)(k)))
#define OBJ_HANDLE(o) (*P32((o) + OBJ_SIZE + 4u * (uint32_t)TYPE_COUNT(OBJ_TYPE(o))))

enum { T_END = 0, T_INT = 1, T_FLT = 2, T_STR = 3, T_CSTR = 4, T_OBJ = 5, T_VEC = 6 };

#define OBJ_NEW_INC 512

static uint32_t* handle_objects = NULL;
static uint32_t  handle_count   = 1;
static uint32_t  handle_cap     = 0;

static void obj_unlink(uint32_t obj)
{
	OBJ_PREV(OBJ_NEXT(obj)) = OBJ_PREV(obj);
	OBJ_NEXT(OBJ_PREV(obj)) = OBJ_NEXT(obj);
}

static void obj_insert(uint32_t obj, uint32_t next)
{
	OBJ_NEXT(obj)           = next;
	OBJ_PREV(obj)           = OBJ_PREV(next);
	OBJ_NEXT(OBJ_PREV(next)) = obj;
	OBJ_PREV(next)          = obj;
}

uint32_t bb32_vec_alloc(uint32_t type)
{
	uint32_t size = *P32(type + 4);
	return bb32_zalloc(size * 4);
}

void bb32_vec_free(uint32_t vec, uint32_t type)
{
	uint32_t size = *P32(type + 4);
	int32_t  tag  = TYPE_TAG(*P32(type + 8));
	if (tag == T_STR) {
		for (uint32_t k = 0; k < size; k++) {
			if (*P32(vec + 4 * k)) {
				bb32_str_release(*P32(vec + 4 * k));
			}
		}
	} else if (tag == T_OBJ) {
		for (uint32_t k = 0; k < size; k++) {
			if (*P32(vec + 4 * k)) {
				bb32_obj_release(*P32(vec + 4 * k));
			}
		}
	}
	bb32_free(vec);
}

void bb32_vec_bounds_ex(void)
{
	bb_runtime_error("Blitz array index out of bounds");
}

void bb32_array_bounds_ex(void)
{
	bb_runtime_error("Array index out of bounds");
}

// BBArray { data, elementType, dims, scales[] }
void bb32_undim_array(uint32_t array)
{
	uint32_t data = *P32(array);
	if (!data) {
		return;
	}
	int32_t type = *I32(array + 4);
	int32_t dims = *I32(array + 8);
	if (type == T_STR || type == T_OBJ) {
		uint32_t size = *P32(array + 12 + 4 * (uint32_t)(dims - 1));
		for (uint32_t k = 0; k < size; k++) {
			uint32_t e = *P32(data + 4 * k);
			if (e) {
				if (type == T_STR) {
					bb32_str_release(e);
				} else {
					bb32_obj_release(e);
				}
			}
		}
	}
	bb32_free(data);
	*P32(array) = 0;
}

void bb32_dim_array(uint32_t array)
{
	int32_t dims = *I32(array + 8);
	for (int32_t k = 0; k < dims; k++) {
		*I32(array + 12 + 4 * (uint32_t)k) += 1;
	}
	for (int32_t k = 1; k < dims; k++) {
		*I32(array + 12 + 4 * (uint32_t)k) *= *I32(array + 12 + 4 * (uint32_t)(k - 1));
	}
	uint32_t size = *P32(array + 12 + 4 * (uint32_t)(dims - 1));
	*P32(array) = bb32_zalloc(size * 4);
}

uint32_t bb32_obj_new(uint32_t type)
{
	if (OBJ_NEXT(TYPE_FREE(type)) == TYPE_FREE(type)) {
		uint32_t size = OBJ_SIZE + 4u * (uint32_t)TYPE_COUNT(type) + 4u;
		uint32_t o    = bb32_zalloc(size * OBJ_NEW_INC);
		for (uint32_t k = 0; k < OBJ_NEW_INC; k++) {
			OBJ_TYPE(o) = type; // So that the handle slot is found.
			obj_insert(o, TYPE_FREE(type));
			o += size;
		}
	}
	uint32_t o = OBJ_NEXT(TYPE_FREE(type));
	obj_unlink(o);
	OBJ_TYPE(o)   = type;
	OBJ_REFS(o)   = 1;
	OBJ_FIELDS(o) = o + OBJ_SIZE;
	OBJ_HANDLE(o) = 0;
	for (int32_t k = 0; k < TYPE_COUNT(type); k++) {
		uint32_t ft = TYPE_FIELD(type, k);
		if (TYPE_TAG(ft) == T_VEC) {
			*P32(o + OBJ_SIZE + 4u * (uint32_t)k) = bb32_vec_alloc(ft);
		} else {
			*P32(o + OBJ_SIZE + 4u * (uint32_t)k) = 0;
		}
	}
	obj_insert(o, TYPE_USED(type));
	return o;
}

void bb32_obj_release(uint32_t obj)
{
	if (!obj || --OBJ_REFS(obj)) {
		return;
	}
	obj_unlink(obj);
	obj_insert(obj, TYPE_FREE(OBJ_TYPE(obj)));
}

void bb32_obj_delete(uint32_t obj)
{
	if (!obj) {
		return;
	}
	uint32_t fields = OBJ_FIELDS(obj);
	if (!fields) {
		return;
	}
	uint32_t type = OBJ_TYPE(obj);
	for (int32_t k = 0; k < TYPE_COUNT(type); k++) {
		uint32_t ft = TYPE_FIELD(type, k);
		uint32_t at = fields + 4u * (uint32_t)k;
		switch (TYPE_TAG(ft)) {
		case T_STR:
			bb32_str_release(*P32(at));
			break;
		case T_OBJ:
			bb32_obj_release(*P32(at));
			break;
		case T_VEC:
			bb32_vec_free(*P32(at), ft);
			break;
		}
	}
	if (OBJ_HANDLE(obj)) {
		handle_objects[OBJ_HANDLE(obj)] = 0;
		OBJ_HANDLE(obj)                 = 0;
	}
	OBJ_FIELDS(obj) = 0;
	bb32_obj_release(obj);
}

void bb32_obj_delete_each(uint32_t type)
{
	uint32_t obj = OBJ_NEXT(TYPE_USED(type));
	while (OBJ_TYPE(obj)) {
		uint32_t next = OBJ_NEXT(obj);
		if (OBJ_FIELDS(obj)) {
			bb32_obj_delete(obj);
		}
		obj = next;
	}
}

void bb32_obj_store(uint32_t var, uint32_t obj)
{
	if (obj) {
		++OBJ_REFS(obj); // First, in case of self-assignment.
	}
	bb32_obj_release(*P32(var));
	*P32(var) = obj;
}

int32_t bb32_obj_compare(uint32_t o1, uint32_t o2)
{
	return (o1 ? OBJ_FIELDS(o1) : 0) != (o2 ? OBJ_FIELDS(o2) : 0);
}

uint32_t bb32_obj_next(uint32_t obj)
{
	do {
		obj = OBJ_NEXT(obj);
		if (!OBJ_TYPE(obj)) {
			return 0;
		}
	} while (!OBJ_FIELDS(obj));
	return obj;
}

uint32_t bb32_obj_prev(uint32_t obj)
{
	do {
		obj = OBJ_PREV(obj);
		if (!OBJ_TYPE(obj)) {
			return 0;
		}
	} while (!OBJ_FIELDS(obj));
	return obj;
}

uint32_t bb32_obj_first(uint32_t type)
{
	return bb32_obj_next(TYPE_USED(type));
}

uint32_t bb32_obj_last(uint32_t type)
{
	return bb32_obj_prev(TYPE_USED(type));
}

void bb32_obj_ins_before(uint32_t o1, uint32_t o2)
{
	if (o1 == o2) {
		return;
	}
	obj_unlink(o1);
	obj_insert(o1, o2);
}

void bb32_obj_ins_after(uint32_t o1, uint32_t o2)
{
	if (o1 == o2) {
		return;
	}
	obj_unlink(o1);
	obj_insert(o1, OBJ_NEXT(o2));
}

int32_t bb32_obj_each_first(uint32_t var, uint32_t type)
{
	bb32_obj_store(var, bb32_obj_first(type));
	return *P32(var) != 0;
}

int32_t bb32_obj_each_next(uint32_t var)
{
	bb32_obj_store(var, bb32_obj_next(*P32(var)));
	return *P32(var) != 0;
}

int32_t bb32_obj_each_first2(uint32_t var, uint32_t type)
{
	*P32(var) = bb32_obj_first(type);
	return *P32(var) != 0;
}

int32_t bb32_obj_each_next2(uint32_t var)
{
	*P32(var) = bb32_obj_next(*P32(var));
	return *P32(var) != 0;
}

static void text_append(char** text, size_t* length, size_t* cap, const char* s, size_t n)
{
	if (*length + n + 1 > *cap) {
		*cap  = (*length + n + 1) * 2;
		*text = (char*)realloc(*text, *cap);
	}
	memcpy(*text + *length, s, n);
	*length += n;
	(*text)[*length] = 0;
}

static void obj_text(uint32_t obj, char** text, size_t* length, size_t* cap)
{
	static uint32_t root;
	static int      recurs_cnt;
	if (!obj || !OBJ_FIELDS(obj)) {
		text_append(text, length, cap, "[NULL]", 6);
		return;
	}
	if (obj == root) {
		text_append(text, length, cap, "[ROOT]", 6);
		return;
	}
	if (recurs_cnt == 8) {
		text_append(text, length, cap, "....", 4);
		return;
	}
	++recurs_cnt;
	uint32_t old_root = root;
	if (!root) {
		root = obj;
	}
	uint32_t type   = OBJ_TYPE(obj);
	uint32_t fields = OBJ_FIELDS(obj);
	text_append(text, length, cap, "[", 1);
	for (int32_t k = 0; k < TYPE_COUNT(type); k++) {
		if (k) {
			text_append(text, length, cap, ",", 1);
		}
		uint32_t at = fields + 4u * (uint32_t)k;
		switch (TYPE_TAG(TYPE_FIELD(type, k))) {
		case T_INT: {
			char* s = (char*)bb_str_from_i64(*I32(at));
			text_append(text, length, cap, s, strlen(s));
			free(s);
			break;
		}
		case T_FLT: {
			float f;
			memcpy(&f, arena + at, 4);
			char* s = (char*)bb_str_from_f64((double)f);
			text_append(text, length, cap, s, strlen(s));
			free(s);
			break;
		}
		case T_STR:
			text_append(text, length, cap, "\"", 1);
			if (*P32(at)) {
				text_append(text, length, cap, strings[*P32(at)].text, strings[*P32(at)].length);
			}
			text_append(text, length, cap, "\"", 1);
			break;
		case T_OBJ:
			obj_text(*P32(at), text, length, cap);
			break;
		default:
			text_append(text, length, cap, "???", 3);
		}
	}
	text_append(text, length, cap, "]", 1);
	root = old_root;
	--recurs_cnt;
}

uint32_t bb32_obj_to_str(uint32_t obj)
{
	char*  text   = NULL;
	size_t length = 0, cap = 0;
	text_append(&text, &length, &cap, "", 0);
	obj_text(obj, &text, &length, &cap);
	return string_alloc(text, length);
}

int32_t bb32_obj_to_handle(uint32_t obj)
{
	if (!obj || !OBJ_FIELDS(obj)) {
		return 0;
	}
	if (OBJ_HANDLE(obj)) {
		return (int32_t)OBJ_HANDLE(obj);
	}
	if (handle_count == handle_cap) {
		handle_cap     = handle_cap ? handle_cap * 2 : 256;
		handle_objects = (uint32_t*)realloc(handle_objects, handle_cap * sizeof(uint32_t));
	}
	uint32_t h         = handle_count++;
	handle_objects[h]  = obj;
	OBJ_HANDLE(obj)    = h;
	return (int32_t)h;
}

uint32_t bb32_obj_from_handle(int32_t handle, uint32_t type)
{
	if (handle <= 0 || (uint32_t)handle >= handle_count) {
		return 0;
	}
	uint32_t obj = handle_objects[handle];
	return (obj && OBJ_TYPE(obj) == type) ? obj : 0;
}

void bb32_null_obj_ex(void)
{
	bb_runtime_error("Object does not exist");
}

////////////////////////////////////////////////////////////////////////////////
// Data: BBData { fieldType, field }, 8 bytes each
////////////////////////////////////////////////////////////////////////////////
static uint32_t data_ptr = 0;

void bb32_restore(uint32_t data)
{
	data_ptr = data;
}

int32_t bb32_read_int(void)
{
	switch (*I32(data_ptr)) {
	case T_END:
		bb_runtime_error("Out of data");
		return 0;
	case T_INT: {
		int32_t n = *I32(data_ptr + 4);
		data_ptr += 8;
		return n;
	}
	case T_FLT: {
		float f;
		memcpy(&f, arena + data_ptr + 4, 4);
		data_ptr += 8;
		return (int32_t)f;
	}
	case T_CSTR: {
		int32_t n = bb_str_to_i32((const char*)(arena + *P32(data_ptr + 4)));
		data_ptr += 8;
		return n;
	}
	default:
		bb_runtime_error("Bad data type");
		return 0;
	}
}

float bb32_read_float(void)
{
	switch (*I32(data_ptr)) {
	case T_END:
		bb_runtime_error("Out of data");
		return 0;
	case T_INT: {
		float n = (float)*I32(data_ptr + 4);
		data_ptr += 8;
		return n;
	}
	case T_FLT: {
		float f;
		memcpy(&f, arena + data_ptr + 4, 4);
		data_ptr += 8;
		return f;
	}
	case T_CSTR: {
		float n = (float)bb_str_to_f64((const char*)(arena + *P32(data_ptr + 4)));
		data_ptr += 8;
		return n;
	}
	default:
		bb_runtime_error("Bad data type");
		return 0;
	}
}

uint32_t bb32_read_str(void)
{
	switch (*I32(data_ptr)) {
	case T_END:
		bb_runtime_error("Out of data");
		return 0;
	case T_INT: {
		uint32_t s = bb32_str_from_int(*I32(data_ptr + 4));
		data_ptr += 8;
		return s;
	}
	case T_FLT: {
		float f;
		memcpy(&f, arena + data_ptr + 4, 4);
		data_ptr += 8;
		return bb32_str_from_float(f);
	}
	case T_CSTR: {
		uint32_t s = bb32_str_from_text((const char*)(arena + *P32(data_ptr + 4)));
		data_ptr += 8;
		return s;
	}
	default:
		bb_runtime_error("Bad data type");
		return 0;
	}
}

////////////////////////////////////////////////////////////////////////////////
// Numbers
////////////////////////////////////////////////////////////////////////////////
int32_t bb32_abs(int32_t n)
{
	return n >= 0 ? n : -n;
}

int32_t bb32_sgn(int32_t n)
{
	return n > 0 ? 1 : (n < 0 ? -1 : 0);
}

int32_t bb32_mod(int32_t x, int32_t y)
{
	if (y == 0) {
		bb_runtime_error("Integer divide by zero");
		return 0;
	}
	if (y == -1) {
		return 0;
	}
	return x % y;
}

float bb32_fabs(float n)
{
	return n >= 0 ? n : -n;
}

float bb32_fsgn(float n)
{
	return n > 0 ? 1.0f : (n < 0 ? -1.0f : 0.0f);
}

float bb32_fmod(float x, float y)
{
	return (float)fmod(x, y);
}

float bb32_fpow(float x, float y)
{
	return (float)pow(x, y);
}

////////////////////////////////////////////////////////////////////////////////
// User libraries: the table of the program lists the libraries and the functions it uses, with the place for each address.
// Libraries of Windows can't be loaded here yet, so the places stay empty and the functions that use them raise an error.
////////////////////////////////////////////////////////////////////////////////
// The characters that a function of a user library returned, as a C string in the arena, which is what the program expects (it turns it into
// a string right after the call, like the original). The library owns the characters and may reuse them, so they are copied, and one copy
// that the next call replaces is enough.
uint32_t bb32_userlib_text(const char* text)
{
	static uint32_t copy = 0;
	bb32_free(copy);
	copy = 0;
	if (text) {
		size_t length = strlen(text);
		copy          = bb32_malloc((uint32_t)length + 1);
		memcpy(arena + copy, text, length + 1);
	}
	return copy;
}

void bb32_load_libs(uint32_t table)
{
	(void)table;
}
